:root {
  --night: #040A0E;
  --obsidian: #071218;
  --ink: #EEFAF6;
  --soft: rgba(218, 242, 234, 0.78);
  --ember: #FFA33E;
  --jade: #5FF2C8;
  --ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --artH: calc(100vw * 1520 / 2688);
  --sprite-url: url("/templates/xibalba/scene-sprites-keyed.webp");
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
.xib-body {
  margin: 0;
  padding: 0;
  background-color: var(--night);
  color: var(--ink);
  font-family: var(--font-inter), 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

::selection {
  background: rgba(95, 242, 200, 0.25);
  color: var(--ink);
}

/* ==========================================================================
   NAVIGATION BAR (.nav)
   ========================================================================== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  height: 64px;
  padding: 0 2.2vw;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  background: linear-gradient(rgba(4, 10, 14, 0.62), transparent);
  transform: translateY(-100%);
  animation: navSlideDown 900ms var(--ease) 500ms forwards;
}

@keyframes navSlideDown {
  from {
    transform: translateY(-100%);
  }
  to {
    transform: translateY(0%);
  }
}

.nav-left {
  display: flex;
  align-items: center;
  gap: 5.6vw;
  justify-self: start;
}

.nav-right {
  display: flex;
  align-items: center;
  gap: 4.2vw;
  justify-self: end;
}

.nav a {
  color: var(--ink);
  text-decoration: none;
  font-family: var(--font-inter), 'Inter', sans-serif;
  font-size: clamp(12px, 0.86vw, 14px);
  font-weight: 500;
  letter-spacing: 0.04em;
  white-space: nowrap;
  transition: color 180ms var(--ease), opacity 180ms var(--ease);
}

.nav-left a:hover,
.nav-right a:hover {
  color: var(--ember);
}

.nav-logo {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  transition: transform 200ms var(--ease);
}

.nav-logo:hover {
  transform: scale(1.08);
}

.nav-cta {
  background: transparent;
  color: var(--ink);
  font-family: var(--font-inter), 'Inter', sans-serif;
  font-size: clamp(12px, 0.86vw, 14px);
  font-weight: 500;
  letter-spacing: 0.04em;
  border: 1px solid rgba(238, 250, 246, 0.6);
  padding: 8px 14px;
  border-radius: 2px;
  line-height: 1;
  cursor: pointer;
  transition: background-color 180ms var(--ease), color 180ms var(--ease), border-color 180ms var(--ease);
}

.nav-cta:hover {
  background: var(--ink);
  color: var(--night);
  border-color: var(--ink);
}

/* ==========================================================================
   CURSOR COPAL TORCH (.lamp)
   ========================================================================== */
.lamp {
  position: fixed;
  left: 0;
  top: 0;
  width: 520px;
  height: 520px;
  border-radius: 50%;
  background: radial-gradient(
    closest-side,
    rgba(255, 170, 80, 0.15),
    rgba(95, 242, 200, 0.05) 55%,
    transparent
  );
  mix-blend-mode: screen;
  pointer-events: none;
  z-index: 40;
  will-change: transform;
  transform: translate3d(-9999px, -9999px, 0);
  contain: strict;
}

/* ==========================================================================
   SCROLLER & SCENE CONTAINERS
   ========================================================================== */
#scroller {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  will-change: transform;
  background-color: var(--night);
}

.scene {
  position: relative;
  width: 100vw;
  height: var(--artH);
  overflow: hidden;
  background-color: var(--night);
  contain: paint layout;
}

.art {
  position: relative;
  width: 100%;
  height: 100%;
  user-select: none;
}

.scene-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: calc(var(--focus, 50) * 1%) center;
  display: block;
  pointer-events: none;
  z-index: 1;
}

/* ==========================================================================
   SEAMS (.seam & .band)
   ========================================================================== */
.seam {
  position: relative;
  height: 0;
  z-index: 10;
  pointer-events: none;
}

.band {
  position: absolute;
  left: 0;
  top: 0;
  width: 100vw;
  aspect-ratio: 16 / 9;
  transform: translateY(-50%);
  pointer-events: none;
}

.seam-img {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: calc(var(--focus, 50) * 1%) center;
  display: block;
  pointer-events: none;
}

/* ==========================================================================
   CANVAS STREAKS, AMBIENT PARTICLES, MIST, MOONGLOW & BRAZIER GLOWS
   ========================================================================== */
canvas.fall {
  position: absolute;
  z-index: 2;
  mix-blend-mode: screen;
  pointer-events: none;
}

canvas.particles {
  position: absolute;
  z-index: 4;
  mix-blend-mode: screen;
  pointer-events: none;
}

.moonglow {
  position: absolute;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(
    circle,
    transparent 58%,
    rgba(255, 230, 165, 0.36) 68%,
    rgba(95, 242, 200, 0.14) 85%,
    transparent 100%
  );
  mix-blend-mode: screen;
  pointer-events: none;
  z-index: 3;
  animation: moonBreathe 6s ease-in-out infinite;
}

@keyframes moonBreathe {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(0.96);
    opacity: 0.82;
  }
  50% {
    transform: translate(-50%, -50%) scale(1.07);
    opacity: 1;
  }
}

.mist {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: radial-gradient(
    ellipse at center,
    rgba(130, 255, 228, 0.36) 0%,
    rgba(70, 215, 190, 0.15) 52%,
    transparent 76%
  );
  filter: blur(8px);
  mix-blend-mode: screen;
  pointer-events: none;
  z-index: 3;
  animation: mistBreathe 5.2s ease-in-out infinite;
}

@keyframes mistBreathe {
  0%,
  100% {
    transform: translate(-50%, -50%) scaleX(0.95) scaleY(0.9);
    opacity: 0.72;
  }
  50% {
    transform: translate(-50%, -50%) scaleX(1.08) scaleY(1.12);
    opacity: 1;
  }
}

.glow {
  position: absolute;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(
    circle,
    rgba(255, 205, 105, 0.56) 0%,
    rgba(255, 142, 42, 0.25) 45%,
    transparent 72%
  );
  mix-blend-mode: screen;
  pointer-events: none;
  z-index: 3;
  animation: flickerWarm 3.4s ease-in-out infinite alternate;
  will-change: transform, opacity;
  contain: strict;
}

.glow.cold {
  background: radial-gradient(
    circle,
    rgba(150, 255, 235, 0.65) 0%,
    rgba(95, 242, 200, 0.28) 45%,
    transparent 72%
  );
  animation: pulseCold 4s ease-in-out infinite alternate;
}

@keyframes flickerWarm {
  0% {
    opacity: 0.75;
    transform: translate(-50%, -50%) scale(0.94);
  }
  30% {
    opacity: 0.95;
    transform: translate(-50%, -50%) scale(1.03);
  }
  70% {
    opacity: 0.82;
    transform: translate(-50%, -50%) scale(0.97);
  }
  100% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1.05);
  }
}

@keyframes pulseCold {
  0% {
    opacity: 0.7;
    transform: translate(-50%, -50%) scale(0.95);
  }
  100% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1.08);
  }
}

/* ==========================================================================
   SPRITES: JADE MORPHO SPIRITS & CAVE BATS
   ========================================================================== */
.sprite {
  position: absolute;
  pointer-events: none;
  z-index: 5;
  background-image: var(--sprite-url);
  background-repeat: no-repeat;
  will-change: transform;
}

.sprite.spirit {
  filter: drop-shadow(0 0 10px rgba(95, 242, 200, 0.48));
}

.sprite.spirit.spirit1 {
  aspect-ratio: 310 / 260;
  background-size: 330.32% 294.23%;
  background-position: 2.1% 8.3%;
}

.sprite.spirit.spirit2 {
  aspect-ratio: 235 / 225;
  background-size: 435.74% 340%;
  background-position: 45.3% 10.1%;
}

.sprite.spirit.spirit3 {
  aspect-ratio: 178 / 292;
  background-size: 575.28% 261.98%;
  background-position: 73.7% 10.1%;
}

.sprite.spirit.spirit4 {
  aspect-ratio: 145 / 520;
  background-size: 706.2% 147.11%;
  background-position: 94.6% 9.7%;
}

.sprite.bat {
  aspect-ratio: 280 / 285;
  width: clamp(26px, 2.2vw, 48px);
  background-size: 365.71% 268.42%;
  background-position: 6% 84.3%;
  opacity: 0.82;
  filter: drop-shadow(0 0 6px rgba(4, 10, 14, 0.9));
  transform: translate(-50%, -50%);
}

.sprite.bat.down {
  aspect-ratio: 435 / 185;
  background-size: 235.4% 413.51%;
  background-position: 60.7% 83.6%;
}

/* ==========================================================================
   SCENE COPY, HEADINGS, AND BUTTONS
   ========================================================================== */
.hero-title-wrap {
  position: absolute;
  left: 50%;
  transform: translate3d(-50%, 0, 0);
  top: calc(var(--artH) * 0.095);
  z-index: 12;
  text-align: center;
  pointer-events: none;
}

.hero-h1 {
  font-family: var(--font-oswald), 'Oswald', sans-serif;
  font-weight: 500;
  font-size: clamp(46px, 6.4vw, 124px);
  letter-spacing: calc(0.42em + var(--lsx, 0em));
  text-transform: uppercase;
  color: var(--ink);
  text-shadow: 0 0 40px rgba(70, 225, 190, 0.45);
  margin: 0;
  line-height: 1;
  display: flex;
  justify-content: center;
}

.hero-h1 span {
  display: inline-block;
  opacity: 0;
  transform: translateY(28px);
  animation: letterRise 900ms var(--ease) forwards;
}

@keyframes letterRise {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.sub {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  top: calc(var(--artH) * 0.37);
  z-index: 12;
  font-family: var(--font-oswald), 'Oswald', sans-serif;
  font-weight: 500;
  font-size: clamp(12px, 1.18vw, 22px);
  letter-spacing: 0.62em;
  text-transform: uppercase;
  color: var(--ink);
  opacity: 0.88;
  margin: 0;
  white-space: nowrap;
}

.copy {
  position: absolute;
  z-index: 12;
  color: var(--ink);
}

.copy h2 {
  font-family: var(--font-oswald), 'Oswald', sans-serif;
  font-weight: 500;
  font-size: clamp(26px, 3.1vw, 54px);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin: 0 0 8px;
  line-height: 1.05;
}

.copy h3 {
  font-family: var(--font-oswald), 'Oswald', sans-serif;
  font-weight: 500;
  font-size: clamp(14px, 1.2vw, 21px);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--jade);
  margin: 12px 0 4px;
}

.copy p {
  font-family: var(--font-inter), 'Inter', sans-serif;
  font-size: clamp(12.5px, 0.95vw, 15.5px);
  line-height: 1.55;
  color: var(--soft);
  margin: 0 0 8px;
}

.rule {
  width: 56px;
  height: 2px;
  background: var(--jade);
  margin-bottom: 12px;
}

.rule.centered {
  margin-left: auto;
  margin-right: auto;
}

.copy-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.reveal-mask {
  display: block;
  overflow: hidden;
}

.reveal-item {
  transform: translateY(105%);
  opacity: 0;
  transition: transform 900ms var(--ease), opacity 900ms var(--ease);
}

.scene.in-view .reveal-item {
  transform: translateY(0%);
  opacity: 1;
}

.btn-row {
  display: flex;
  gap: 16px;
  margin-top: 24px;
}

.btn-row.centered {
  justify-content: center;
}

.btn-solid {
  background: var(--ink);
  color: var(--night);
  border: 1px solid var(--ink);
  padding: 12px 24px;
  border-radius: 2px;
  font-family: var(--font-inter), 'Inter', sans-serif;
  font-size: clamp(13px, 0.95vw, 15px);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 180ms var(--ease), transform 180ms var(--ease);
}

.btn-solid:hover {
  background: var(--ember);
  border-color: var(--ember);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border: 1px solid rgba(238, 250, 246, 0.6);
  padding: 12px 24px;
  border-radius: 2px;
  font-family: var(--font-inter), 'Inter', sans-serif;
  font-size: clamp(13px, 0.95vw, 15px);
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 180ms var(--ease), border-color 180ms var(--ease), color 180ms var(--ease);
}

.btn-ghost:hover {
  background: rgba(238, 250, 246, 0.12);
  border-color: var(--ink);
}

.btn-sm {
  padding: 6px 14px;
  font-size: 11px;
}

/* ==========================================================================
   MODALS (Codex, Map, Reserve)
   ========================================================================== */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(4, 10, 14, 0.88);
  backdrop-filter: blur(12px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.modal-panel {
  position: relative;
  width: 100%;
  max-width: 680px;
  max-height: 88vh;
  overflow-y: auto;
  background: var(--obsidian);
  border: 1px solid rgba(95, 242, 200, 0.28);
  padding: clamp(24px, 3.4vw, 44px);
  border-radius: 4px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.85);
}

.modal-close {
  position: absolute;
  top: 18px;
  right: 20px;
  background: transparent;
  border: none;
  color: var(--ink);
  font-family: var(--font-inter), sans-serif;
  font-size: 14px;
  cursor: pointer;
  opacity: 0.7;
  transition: opacity 160ms var(--ease);
}

.modal-close:hover {
  opacity: 1;
}

.modal-kicker {
  font-family: var(--font-oswald), sans-serif;
  font-size: 12px;
  letter-spacing: 0.16em;
  color: var(--jade);
  text-transform: uppercase;
  margin: 0 0 6px;
}

.modal-title {
  font-family: var(--font-oswald), sans-serif;
  font-size: clamp(24px, 2.8vw, 38px);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin: 0 0 14px;
}

.modal-rule {
  margin-bottom: 24px;
}

.codex-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  border-bottom: 1px solid rgba(238, 250, 246, 0.15);
  padding-bottom: 8px;
}

.codex-tab {
  background: transparent;
  border: none;
  color: var(--ink);
  font-family: var(--font-oswald), sans-serif;
  font-size: 14px;
  letter-spacing: 0.1em;
  padding: 8px 16px;
  cursor: pointer;
  opacity: 0.55;
  transition: opacity 160ms var(--ease), color 160ms var(--ease);
}

.codex-tab.active {
  opacity: 1;
  color: var(--jade);
  border-bottom: 2px solid var(--jade);
}

.codex-folio-card {
  background: rgba(4, 10, 14, 0.6);
  border: 1px solid rgba(238, 250, 246, 0.1);
  padding: 24px;
  border-radius: 2px;
  margin-bottom: 24px;
}

.codex-meta-row {
  display: flex;
  gap: 8px;
  font-family: var(--font-inter), sans-serif;
  font-size: 12px;
  color: var(--jade);
  margin-bottom: 12px;
}

.codex-folio-heading {
  font-family: var(--font-oswald), sans-serif;
  font-size: 22px;
  margin: 0 0 12px;
}

.codex-folio-body {
  font-family: var(--font-inter), sans-serif;
  font-size: 14px;
  line-height: 1.65;
  color: var(--soft);
  margin: 0 0 16px;
}

.codex-rite-box {
  border-left: 2px solid var(--ember);
  padding-left: 14px;
}

.codex-rite-label {
  display: block;
  font-family: var(--font-oswald), sans-serif;
  font-size: 11px;
  letter-spacing: 0.14em;
  color: var(--ember);
  text-transform: uppercase;
  margin-bottom: 4px;
}

.codex-rite-box p {
  font-family: var(--font-inter), sans-serif;
  font-size: 13px;
  margin: 0;
  color: var(--soft);
}

.modal-footer-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

.descent-station-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.descent-station-item {
  background: rgba(4, 10, 14, 0.5);
  border: 1px solid rgba(238, 250, 246, 0.1);
  padding: 16px 20px;
  border-radius: 2px;
}

.descent-station-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 10px;
}

.descent-depth-tag {
  display: inline-block;
  font-size: 11px;
  color: var(--jade);
  font-weight: 600;
  margin-bottom: 4px;
}

.descent-station-title {
  font-family: var(--font-oswald), sans-serif;
  font-size: 18px;
  margin: 0 0 2px;
}

.descent-station-sub {
  font-size: 12px;
  color: var(--soft);
  margin: 0;
}

.descent-highlights {
  display: flex;
  gap: 8px;
  font-size: 11px;
  color: rgba(218, 242, 234, 0.65);
}

.reserve-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-field label {
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--ink);
}

.form-field input,
.form-field select {
  background: rgba(4, 10, 14, 0.85);
  border: 1px solid rgba(238, 250, 246, 0.25);
  color: var(--ink);
  padding: 10px 14px;
  border-radius: 2px;
  font-family: var(--font-inter), sans-serif;
  font-size: 14px;
  outline: none;
  transition: border-color 160ms var(--ease);
}

.form-field input:focus,
.form-field select:focus {
  border-color: var(--jade);
}

.form-row-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.field-error {
  font-size: 11px;
  color: var(--ember);
}

.reservation-confirmed {
  text-align: center;
  padding: 24px 0;
}

.confirmed-kicker {
  font-family: var(--font-oswald), sans-serif;
  font-size: 13px;
  letter-spacing: 0.16em;
  color: var(--jade);
  text-transform: uppercase;
}

.confirmed-code {
  font-family: var(--font-oswald), sans-serif;
  font-size: clamp(32px, 4vw, 48px);
  color: var(--ember);
  margin: 12px 0 16px;
}

.confirmed-details {
  font-size: 14px;
  color: var(--soft);
  margin-bottom: 24px;
}

.existing-reservations-note {
  font-size: 12px;
  color: var(--jade);
}

/* ==========================================================================
   STATIC FALLBACK PAGE (SSR, Reduced Motion, No-JS)
   ========================================================================== */
.xib-static-fallback {
  display: none;
  background-color: var(--night);
  color: var(--ink);
  padding: 40px 24px 80px;
  min-height: 100vh;
}

.xib-fallback-header {
  max-width: 1040px;
  margin: 0 auto 60px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(238, 250, 246, 0.15);
  padding-bottom: 24px;
}

.xib-fallback-brand {
  display: flex;
  align-items: center;
  gap: 16px;
}

.xib-fallback-logo {
  font-family: var(--font-oswald), sans-serif;
  font-size: 24px;
  letter-spacing: 0.2em;
  margin: 0;
}

.xib-fallback-sublogo {
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--jade);
  margin: 0;
}

.xib-fallback-nav {
  display: flex;
  gap: 20px;
}

.xib-fallback-nav a {
  color: var(--soft);
  text-decoration: none;
  font-size: 13px;
}

.xib-fallback-nav a:hover {
  color: var(--ember);
}

.xib-fallback-hero,
.xib-fallback-section {
  max-width: 1040px;
  margin: 0 auto 64px;
}

.xib-fallback-hero-content {
  text-align: center;
}

.xib-kicker {
  display: inline-block;
  font-family: var(--font-oswald), sans-serif;
  font-size: 12px;
  letter-spacing: 0.16em;
  color: var(--jade);
  margin-bottom: 8px;
}

.xib-fallback-title {
  font-family: var(--font-oswald), sans-serif;
  font-size: clamp(48px, 6vw, 92px);
  letter-spacing: 0.35em;
  margin: 0 0 16px;
}

.xib-fallback-lead {
  max-width: 680px;
  margin: 0 auto 36px;
  font-size: 16px;
  line-height: 1.65;
  color: var(--soft);
}

.xib-fallback-plate {
  margin-top: 24px;
  background: var(--obsidian);
  border: 1px solid rgba(95, 242, 200, 0.2);
  border-radius: 4px;
  overflow: hidden;
}

.xib-fallback-plate img {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  display: block;
}

.xib-plate-caption {
  display: block;
  padding: 12px 18px;
  font-size: 12px;
  color: var(--soft);
  text-align: left;
  border-top: 1px solid rgba(238, 250, 246, 0.1);
}

.xib-fallback-section-inner h2 {
  font-family: var(--font-oswald), sans-serif;
  font-size: clamp(26px, 3vw, 42px);
  margin: 0 0 14px;
}

.xib-fallback-section-inner p {
  color: var(--soft);
  line-height: 1.65;
  margin: 0 0 16px;
  max-width: 720px;
}

.xib-fallback-folios {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 24px;
}

.xib-folio-entry {
  background: var(--obsidian);
  border: 1px solid rgba(238, 250, 246, 0.12);
  padding: 20px;
  border-radius: 3px;
}

.xib-folio-meta {
  font-size: 11px;
  color: var(--jade);
  display: block;
  margin-bottom: 6px;
}

.xib-folio-entry h3 {
  font-family: var(--font-oswald), sans-serif;
  font-size: 18px;
  margin: 0 0 8px;
}

.xib-folio-entry p {
  font-size: 13px;
  line-height: 1.6;
}

.xib-folio-rite {
  font-size: 12px;
  color: var(--ember);
  margin-top: 10px;
}

.xib-stations-table {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}

.xib-station-row {
  display: flex;
  gap: 24px;
  background: var(--obsidian);
  border: 1px solid rgba(238, 250, 246, 0.1);
  padding: 16px;
  border-radius: 3px;
}

.xib-station-depth {
  font-family: var(--font-oswald), sans-serif;
  font-size: 20px;
  color: var(--jade);
  min-width: 70px;
}

.xib-station-info h4 {
  margin: 0 0 4px;
  font-family: var(--font-oswald), sans-serif;
  font-size: 16px;
}

.xib-station-time {
  font-size: 12px;
  color: var(--soft);
  margin: 0 0 8px;
}

.xib-station-tags {
  display: flex;
  gap: 12px;
  list-style: none;
  padding: 0;
  margin: 0;
  font-size: 11px;
  color: rgba(218, 242, 234, 0.7);
}

.xib-fallback-footer {
  max-width: 1040px;
  margin: 60px auto 0;
  border-top: 1px solid rgba(238, 250, 246, 0.15);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: rgba(218, 242, 234, 0.5);
}

/* ==========================================================================
   REDUCED MOTION & ACCESSIBILITY OVERRIDES
   ========================================================================== */
@media (prefers-reduced-motion: reduce) {
  .xib-static-fallback {
    display: block;
  }
  .xib-interactive-root {
    display: none;
  }
  .glow,
  .moonglow,
  .mist {
    animation: none !important;
  }
  .hero-h1 span {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .reveal-item {
    transform: none !important;
    opacity: 1 !important;
  }
}
